function sanitize(value) {
  return String(value || 'Error no especificado')
    .replace(/[\u0000-\u001f\u007f]+/g, ' ')
    .replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, '[email]')
    .replace(/\bAuthorization\s*[:=]\s*(?:Bearer\s+)?[^\s,;]+/gi, 'Authorization=[redacted]')
    .replace(/\bBearer\s+[A-Za-z0-9._~+/=-]+/gi, 'Bearer [redacted]')
    .replace(/\b[a-z_]*(?:role|key|token|password|secret|credential)[a-z_]*\s*[:=]\s*[^\s,;]+/gi, '[redacted]')
    .replace(/\bsb_[a-z]+_[A-Za-z0-9_-]+/gi, '[redacted]')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 500);
}

return $input.all().map((item) => ({
  json: {
    occurred_at: new Date().toISOString(),
    workflow_name: sanitize(item.json.workflow?.name || 'No especificado'),
    failed_node: sanitize(
      item.json.execution?.lastNodeExecuted ||
      item.json.trigger?.error?.node?.name ||
      'No especificado'
    ),
    execution_id: sanitize(item.json.execution?.id || 'No especificado'),
    error_message: sanitize(
      item.json.execution?.error?.message ||
      item.json.trigger?.error?.message ||
      item.json.trigger?.error?.cause?.message
    ),
    handling_status: 'pending_output_configuration',
  },
}));
